using System.ComponentModel.DataAnnotations;
using EduSphere.Domain.Entities;
using EduSphere.Domain.Enums;
using EduSphere.Infrastructure;
using EduSphere.Web.Authorization;
using EduSphere.Web.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.EntityFrameworkCore;

namespace EduSphere.Web.Pages.Enterprise;

[Authorize(Policy=AuthorizationPolicies.TransportManager)]
public sealed class TransportDepthModel(TenantDbContext db,ITransportDepthService transport,IWebHostEnvironment env,TransportSecretProtector secrets):PageModel
{
    public IReadOnlyList<Branch> Branches{get;private set;}=[]; public IReadOnlyList<Vehicle> Vehicles{get;private set;}=[]; public IReadOnlyList<TransportRoute> Routes{get;private set;}=[]; public IReadOnlyList<StudentProfile> Students{get;private set;}=[];
    public IReadOnlyList<TransportGpsProviderSetting> Providers{get;private set;}=[];public IReadOnlyList<TransportCrewProfile> Crew{get;private set;}=[];public IReadOnlyList<VehicleDocument> Documents{get;private set;}=[];public IReadOnlyList<TransportGeofence> Geofences{get;private set;}=[];public IReadOnlyList<VehicleFuelLog> FuelLogs{get;private set;}=[];public IReadOnlyList<TransportAttendanceScan> Scans{get;private set;}=[];public IReadOnlyList<RouteOptimizationRun> Optimizations{get;private set;}=[];public IReadOnlyList<VehicleGpsPing> LatestPositions{get;private set;}=[];
    [BindProperty]public ProviderInput ProviderForm{get;set;}=new();[BindProperty]public CrewInput CrewForm{get;set;}=new();[BindProperty]public DocumentInput DocumentForm{get;set;}=new();[BindProperty]public GeofenceInput GeofenceForm{get;set;}=new();[BindProperty]public FuelInput FuelForm{get;set;}=new();[BindProperty]public ScanInput ScanForm{get;set;}=new();[BindProperty]public Guid OptimizeRouteId{get;set;}[BindProperty]public DateOnly FeeMonth{get;set;}=new(DateTime.UtcNow.Year,DateTime.UtcNow.Month,1);
    public sealed class ProviderInput{public Guid? BranchId{get;set;}[Required,StringLength(120)]public string Name{get;set;}="";public GpsProviderType ProviderType{get;set;}=GpsProviderType.GenericWebhook;[StringLength(500)]public string? EndpointUrl{get;set;}[StringLength(2000)]public string? ApiKey{get;set;}}
    public sealed class CrewInput{[Required]public Guid? BranchId{get;set;}public TransportCrewRole Role{get;set;}[Required,StringLength(160)]public string FullName{get;set;}="";[Required,StringLength(30)]public string PhoneNumber{get;set;}="";[StringLength(60)]public string? EmployeeNumber{get;set;}[StringLength(60)]public string? LicenseNumber{get;set;}public DateOnly? LicenseValidUntil{get;set;}[StringLength(80)]public string? RfidTag{get;set;}}
    public sealed class DocumentInput{[Required]public Guid? BranchId{get;set;}[Required]public Guid? VehicleId{get;set;}public VehicleDocumentType DocumentType{get;set;}[Required]public IFormFile? File{get;set;}[StringLength(100)]public string? DocumentNumber{get;set;}public DateOnly? IssuedOn{get;set;}public DateOnly? ExpiresOn{get;set;}}
    public sealed class GeofenceInput{[Required]public Guid? BranchId{get;set;}public Guid? TransportRouteId{get;set;}[Required,StringLength(160)]public string Name{get;set;}="";[Range(-90,90)]public decimal Latitude{get;set;}[Range(-180,180)]public decimal Longitude{get;set;}[Range(25,5000)]public int RadiusMeters{get;set;}=250;public bool NotifyParents{get;set;}=true;}
    public sealed class FuelInput{[Required]public Guid? BranchId{get;set;}[Required]public Guid? VehicleId{get;set;}public DateOnly FueledOn{get;set;}=DateOnly.FromDateTime(DateTime.UtcNow);[Range(.01,10000)]public decimal Litres{get;set;}[Range(0,100000)]public decimal UnitPrice{get;set;}[Range(0,int.MaxValue)]public int OdometerReading{get;set;}[StringLength(120)]public string? Vendor{get;set;}}
    public sealed class ScanInput{[Required]public Guid? BranchId{get;set;}[Required]public Guid? StudentProfileId{get;set;}[Required]public Guid? VehicleId{get;set;}public Guid? TransportRouteId{get;set;}public TransportAttendanceEvent Event{get;set;}public TransportScanMethod ScanMethod{get;set;}=TransportScanMethod.Qr;[Required,StringLength(160)]public string Token{get;set;}="";}
    public async Task OnGetAsync()=>await Load();
    public async Task<IActionResult> OnPostProviderAsync(){if(!ModelState.IsValid){await Load();return Page();}var token=Convert.ToHexString(System.Security.Cryptography.RandomNumberGenerator.GetBytes(24)).ToLowerInvariant();db.TransportGpsProviderSettings.Add(new(){BranchId=ProviderForm.BranchId,Name=ProviderForm.Name.Trim(),ProviderType=ProviderForm.ProviderType,EndpointUrl=ProviderForm.EndpointUrl?.Trim(),ProtectedApiKey=string.IsNullOrWhiteSpace(ProviderForm.ApiKey)?null:secrets.Protect(ProviderForm.ApiKey),WebhookTokenHash=TransportSecretProtector.HashToken(token)});await db.SaveChangesAsync();TempData["Success"]=$"GPS provider saved. Copy this webhook URL now: /api/transport/gps/webhook/{token}";return RedirectToPage();}
    public async Task<IActionResult> OnPostCrewAsync(){if(!ModelState.IsValid){await Load();return Page();}db.TransportCrewProfiles.Add(new(){BranchId=CrewForm.BranchId!.Value,Role=CrewForm.Role,FullName=CrewForm.FullName.Trim(),PhoneNumber=CrewForm.PhoneNumber.Trim(),EmployeeNumber=CrewForm.EmployeeNumber?.Trim(),LicenseNumber=CrewForm.LicenseNumber?.Trim(),LicenseValidUntil=CrewForm.LicenseValidUntil,RfidTag=CrewForm.RfidTag?.Trim()});await db.SaveChangesAsync();TempData["Success"]="Crew profile created.";return RedirectToPage();}
    public async Task<IActionResult> OnPostDocumentAsync(){if(DocumentForm.File is{Length:>10_000_000})ModelState.AddModelError("DocumentForm.File","Maximum file size is 10 MB.");if(!ModelState.IsValid){await Load();return Page();}var vehicle=await db.Vehicles.FirstOrDefaultAsync(x=>x.Id==DocumentForm.VehicleId&&x.BranchId==DocumentForm.BranchId);if(vehicle is null)return NotFound();var root=Path.Combine(env.ContentRootPath,"App_Data","TransportDocuments",vehicle.TenantId.ToString("N"),vehicle.Id.ToString("N"));Directory.CreateDirectory(root);var safe=$"{Guid.NewGuid():N}{Path.GetExtension(DocumentForm.File!.FileName)}";var path=Path.Combine(root,safe);await using(var stream=System.IO.File.Create(path))await DocumentForm.File.CopyToAsync(stream);db.VehicleDocuments.Add(new(){BranchId=vehicle.BranchId,VehicleId=vehicle.Id,DocumentType=DocumentForm.DocumentType,FileName=Path.GetFileName(DocumentForm.File.FileName),StoragePath=path,ContentType=DocumentForm.File.ContentType,DocumentNumber=DocumentForm.DocumentNumber,IssuedOn=DocumentForm.IssuedOn,ExpiresOn=DocumentForm.ExpiresOn});await db.SaveChangesAsync();return RedirectToPage();}
    public async Task<IActionResult> OnGetDocumentAsync(Guid id){var d=await db.VehicleDocuments.FirstOrDefaultAsync(x=>x.Id==id);if(d is null||!System.IO.File.Exists(d.StoragePath))return NotFound();return PhysicalFile(d.StoragePath,d.ContentType??"application/octet-stream",d.FileName);}
    public async Task<IActionResult> OnPostGeofenceAsync(){if(!ModelState.IsValid){await Load();return Page();}db.TransportGeofences.Add(new(){BranchId=GeofenceForm.BranchId!.Value,TransportRouteId=GeofenceForm.TransportRouteId,Name=GeofenceForm.Name.Trim(),Latitude=GeofenceForm.Latitude,Longitude=GeofenceForm.Longitude,RadiusMeters=GeofenceForm.RadiusMeters,NotifyParents=GeofenceForm.NotifyParents});await db.SaveChangesAsync();return RedirectToPage();}
    public async Task<IActionResult> OnPostFuelAsync(){if(!ModelState.IsValid){await Load();return Page();}db.VehicleFuelLogs.Add(new(){BranchId=FuelForm.BranchId!.Value,VehicleId=FuelForm.VehicleId!.Value,FueledOn=FuelForm.FueledOn,Litres=FuelForm.Litres,UnitPrice=FuelForm.UnitPrice,TotalCost=FuelForm.Litres*FuelForm.UnitPrice,OdometerReading=FuelForm.OdometerReading,Vendor=FuelForm.Vendor});await db.SaveChangesAsync();return RedirectToPage();}
    public async Task<IActionResult> OnPostScanAsync(){if(!ModelState.IsValid){await Load();return Page();}db.TransportAttendanceScans.Add(new(){BranchId=ScanForm.BranchId!.Value,StudentProfileId=ScanForm.StudentProfileId!.Value,VehicleId=ScanForm.VehicleId!.Value,TransportRouteId=ScanForm.TransportRouteId,Event=ScanForm.Event,ScanMethod=ScanForm.ScanMethod,Token=ScanForm.Token.Trim()});await db.SaveChangesAsync();return RedirectToPage();}
    public async Task<IActionResult> OnPostOptimizeAsync(){await transport.OptimizeRouteAsync(OptimizeRouteId);return RedirectToPage();}
    public async Task<IActionResult> OnPostGenerateFeesAsync(){var end=FeeMonth.AddMonths(1).AddDays(-1);var count=await transport.GenerateMonthlyChargesAsync(FeeMonth,end);TempData["Success"]=$"Generated {count} transport fee invoices.";return RedirectToPage();}
    private async Task Load(){Branches=await db.Branches.OrderBy(x=>x.Name).ToListAsync();Vehicles=await db.Vehicles.OrderBy(x=>x.RegistrationNumber).ToListAsync();Routes=await db.TransportRoutes.OrderBy(x=>x.Name).ToListAsync();Students=await db.StudentProfiles.OrderBy(x=>x.FirstName).ToListAsync();Providers=await db.TransportGpsProviderSettings.OrderBy(x=>x.Name).ToListAsync();Crew=await db.TransportCrewProfiles.OrderBy(x=>x.FullName).ToListAsync();Documents=await db.VehicleDocuments.OrderByDescending(x=>x.UploadedOn).Take(50).ToListAsync();Geofences=await db.TransportGeofences.OrderBy(x=>x.Name).ToListAsync();FuelLogs=await db.VehicleFuelLogs.OrderByDescending(x=>x.FueledOn).Take(50).ToListAsync();Scans=await db.TransportAttendanceScans.Include(x=>x.StudentProfile).OrderByDescending(x=>x.ScannedOn).Take(50).ToListAsync();Optimizations=await db.RouteOptimizationRuns.OrderByDescending(x=>x.RequestedOn).Take(20).ToListAsync();LatestPositions=(await db.VehicleGpsPings.OrderByDescending(x=>x.RecordedOn).Take(200).ToListAsync()).GroupBy(x=>x.VehicleId).Select(x=>x.First()).ToList();}
    public string VehicleName(Guid id)=>Vehicles.FirstOrDefault(x=>x.Id==id)?.RegistrationNumber??"-"; public string RouteName(Guid? id)=>Routes.FirstOrDefault(x=>x.Id==id)?.Name??"-";
}
